insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 1, 'The Relief and Flare Studio answers four questions over one facility. Which four are they?', '["What orifice a pressure safety valve needs, what load a pool fire puts on it, what pressure the flare tip can accept, and which contingency on a vessel governs the size.", "What orifice a pressure safety valve needs, what load a pool fire puts on it, what drum keeps liquid out of the flare header, and how long a vessel takes to depressure.", "What set pressure a protected vessel is entitled to, what load a pool fire puts on it, what drum keeps liquid out of the flare header, and how long a vessel depressures.", "What orifice a pressure safety valve needs, what relief load each contingency puts on it, what drum keeps the flare header dry, and what setback the flare tip demands."]'::jsonb, 1, 'A set pressure is stated by the caller rather than worked out, a setback belongs to the separation course, and nothing here ranks one contingency against another.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 2, 'Every sizing route in this module takes a relief load as an input except one. Which route computes its own load, and from what?', '["The gas and vapour route, from the relieving pressure and the gas properties, since a choked throat fixes a mass flux.", "The steam route, because saturated steam at a stated pressure is a defined state the published equation folds up.", "The liquid route, from the differential across the valve and the specific gravity, which together fix a rate.", "The API 521 fire case, from the geometry of the vessel, a drainage answer and an environment factor that the caller states."]'::jsonb, 3, 'A choked throat and a defined steam state both fix a flux rather than a load, and the liquid route sizes for a rate it was handed. Only the fire case builds a load, and even then the drainage answer and the environment factor are stated.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 3, 'Reading the module counts 22 exports. How do they divide?', '["Seven return a bare number and signal a refusal with NaN, twelve return an object, two are published tables and one is a derived constant.", "Twelve return a bare number and signal a refusal with NaN, seven return an object, two are published tables and one is a measured constant.", "Seven return a bare number and throw on a refusal, twelve return an object, two are published tables and one is a derived constant.", "Seven return a bare number and signal a refusal with NaN, twelve return an object, and three are published tables with a constant inside each."]'::jsonb, 0, 'The split is seven bare numbers against twelve objects, with two tables and one derived constant beside them. Nothing in this module throws, and the constant is derived rather than typed.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 4, 'A caller guards every call with a test on the returned `error` field. What does that guard fail to catch?', '["An object with an `error` string whose other fields are all finite.", "A bare number export returning NaN, which such a test is written to see.", "A non finite number arriving in a returned object with no `error` field beside it.", "A published table returning fewer rows than the caller expected of it."]'::jsonb, 2, 'The contract is a finite result or an object carrying an `error` string. The failure the guard cannot see is the pairing it does not cover, a non finite number with no error beside it, which is why every route is audited against both halves.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 5, 'One refusal in this module carries more than an `error` string. Which, and what else does it carry?', '["The steam route above the top of its published range, which also returns the last correction it was able to evaluate.", "The orifice selection past the largest orifice, which also returns `multipleOfT`, a whole number of valves.", "The liquid route below the certified envelope, which also returns the device class the correction suggests instead.", "The gas route with an out of range coefficient, which also returns the bound that coefficient fell outside."]'::jsonb, 1, 'Every other refusal in this module carries the `error` alone. A caller that stops at the `error` throws away the only figure that refusal worked out, which is how many of the largest orifice the area needs.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 6, 'ORUBIRI states a set pressure of 420.000000 psig and an overpressure of 10.000000 percent. What is the relieving pressure?', '["476.700000 psia, the set pressure raised by the overpressure fraction and converted with the measured atmospheric constant.", "The set pressure raised by the overpressure fraction and left as it stands, since that figure is already an absolute pressure.", "The set pressure converted to absolute with 14.700000000000 psia first, and the overpressure fraction applied to the result.", "476.700000 psig, the same arithmetic reported in the gauge unit the set pressure was stated in."]'::jsonb, 0, 'The overpressure is applied to the gauge set pressure and the atmospheric constant is added afterwards. The gas route needs that pressure absolute, so the answer is in psia.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 7, 'The same load and valve are run at four overpressure allowances. What does the sweep show?', '["A larger allowance raises the relieving pressure and raises the required area, and all four rows stay on the same flow branch.", "A larger allowance raises the relieving pressure and lowers the required area, and the branch turns over between the third row and the fourth.", "A larger allowance leaves the relieving pressure alone and lowers the required area, because only the differential across the valve moves.", "A larger allowance raises the relieving pressure and lowers the required area, and all four rows stay on the same flow branch."]'::jsonb, 3, 'The area falls from 2.223779 in2 to 1.964194 in2 as the allowance rises from 10.000000 to 25.000000 percent, and every row is reported critical, so no change of regime is confounding the reading.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 8, 'Three quantities elsewhere on this platform are called back pressure. Which one does this course mean?', '["The choke setting that a managed pressure drilling system holds on the annulus return.", "The term the Rawlins and Schellhardt equation fits on a gas well test.", "The pressure at the relief valve outlet, in the header the valve discharges into.", "The pressure a flare tip imposes on the whole collection system upstream of it."]'::jsonb, 2, 'The choke setting and the deliverability term are the two senses this platform already carries elsewhere. Here it is the outlet pressure on the valve, and it is written that way at every mention.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 9, 'The ORUBIRI outlet pressure reaches the engine in three renderings: 35.000000 psig, 49.700000 psia and 0.104258. Which one does the branch decision read?', '["0.104258, the absolute outlet pressure as a fraction of the relieving pressure.", "49.700000 psia, because the branch decision is a comparison between two absolute pressures.", "35.000000 psig, because the gauge figure is the one a plant document and an instrument both carry.", "All three in turn, since the decision is made once in each unit and the three answers are required to agree."]'::jsonb, 0, 'The decision reads a ratio. The two pressures are what that ratio is built from, and a learner who moves an outlet pressure and watches nothing happen has usually moved a number the comparison does not read directly.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 10, 'AKASO states a set pressure of 310.000000 psig, an overpressure of 10.000000 percent and an outlet pressure of 40.000000 psig. What does the liquid route work on?', '["A relieving pressure of 341.000000 psia, converted with the atmospheric constant before the outlet pressure is subtracted from it.", "A differential of 301.000000 psi, between a relieving pressure of 341.000000 psig and the stated outlet pressure.", "A differential between the relieving pressure and the atmospheric constant of 14.700000000000 psia, since the header is open to atmosphere.", "A differential between the stated set pressure and the stated outlet pressure, with the overpressure allowance applied afterwards."]'::jsonb, 1, 'The liquid route takes both pressures in psig and works on their difference, so the atmospheric constant never enters it. The allowance is applied before the subtraction, which is what puts the relieving pressure at 341.000000 psig.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 11, 'Which statement about the pressures the two routes take is correct?', '["Both routes take absolute pressures, and the liquid route converts its stated gauge figures on the way in.", "The gas route takes a gauge outlet pressure and the liquid route an absolute one, which is why only the liquid route needs the atmospheric constant.", "The gas route is the only one that takes an absolute outlet pressure, and the liquid route works on a difference of two gauge pressures.", "Both routes work on a difference, so neither of them needs a datum and neither carries the atmospheric constant."]'::jsonb, 2, 'A mass flux through a throat depends on an absolute upstream pressure, and a pressure drop is indifferent to the datum. Mixing the two conventions goes wrong by about one atmosphere, which is small enough to read as a rounding difference.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 12, 'The atmospheric constant of 14.700000000000 psia is not exported. How is it established?', '["By reading it off the module source, where it sits as a named constant beside the leading constants of the four routes.", "By subtracting a stated gauge set pressure from the absolute relieving pressure the engine returns for the same case.", "By taking the published value the standard states and confirming that the engine agrees with it to twelve decimals.", "By asking the engine three questions whose answer is that constant and nothing else, one of them through the blowdown march, and all three return it."]'::jsonb, 3, 'This digest never types a number the engine keeps to itself. It arranges a call whose only possible answer is that constant and says which call, and here three separate arrangements agree, one of them in the blowdown march own choked flow floor.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 13, 'Which of these figures does the engine take as a typed input rather than compute?', '["The subcritical factor F2, which is published as a two axis chart.", "The balanced bellows back pressure factor Kb, which is a published chart.", "The critical pressure ratio, which is a published table against k.", "The viscosity correction Kv, a published curve on Reynolds number."]'::jsonb, 1, 'F2, the critical pressure ratio and Kv are all closed forms this engine evaluates on the inputs it was given. The typed set is Kb for gas, Kw for liquid, the superheat factor KSH and the API 526 orifice table.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 14, 'Four leading constants were measured out of this engine. Which figure belongs to which route?', '["520.000000000000 leads the gas coefficient, 735.000000000000 the subcritical form, 38.000000000000 the liquid equation and 51.500000000000 the steam one.", "520.000000000000 leads the gas coefficient, 735.000000000000 the steam equation, 38.000000000000 the liquid one and 51.500000000000 the subcritical form.", "735.000000000000 leads the gas coefficient, 520.000000000000 the subcritical form, 51.500000000000 the liquid equation and 38.000000000000 the steam one.", "520.000000000000 leads the gas coefficient, 735.000000000000 the subcritical form, 2800.000000000000 the liquid equation and 51.500000000000 the steam one."]'::jsonb, 0, 'Each was recovered by arranging a call in which every other factor is one. The 2800.000000000000 belongs to the liquid Reynolds relation rather than to the area equation in front of it.'),
  ('relief', 'beginner', 'module', 'm01-what-a-relief-valve-is-sized-for', 15, 'At what precision does this course report a required area, a flow and a measured constant?', '["An area to four decimals, a flow to six and a measured constant to twelve.", "An area to six decimals, a flow to six and a measured constant to four.", "An area to six decimals, a flow to four and a measured constant to twelve.", "An area to twelve decimals, a flow to six and a measured constant to six."]'::jsonb, 2, 'Areas, pressures and dimensionless ratios print to six decimals, flows and duties to four, and measured constants to twelve. Quoting a figure at a precision nobody declared is how two correct readings come to look like a disagreement.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 1, 'The coefficient C in the critical gas equation is what kind of number in this engine?', '["A chart value the caller types in, with its published reference named beside it.", "A closed form evaluated on every call, from the exponent and the pressure ratio.", "A closed form evaluated on every call, from the isentropic exponent alone.", "A table the engine carries, interpolated between the exponents it lists."]'::jsonb, 2, 'C is computed from the exponent and nothing else, which is why the digest can walk it across a column of stated exponents. The factor needing two inputs is F2, and the typed factor on this route is Kb.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 2, 'Walked from an exponent of 1.050000 to one of 1.800000, C runs from 321.187587 to 387.182334. What does that direction mean for a fixed load?', '["A stiffer gas has a larger C, and a larger C gives a smaller required area.", "A stiffer gas has a larger C, and a larger C gives a larger required area.", "A stiffer gas has a larger C, and the required area is unchanged by it.", "A stiffer gas has a smaller C, and a smaller C gives a larger required area."]'::jsonb, 0, 'C rises monotonically across every exponent printed, and it sits where a larger value shrinks the area the same load needs. The column is a property of the closed form rather than a fit to measurements.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 3, 'Across the same range the critical pressure ratio falls from 0.595386 to 0.469042. What does a smaller critical ratio mean in practice?', '["A stiffer gas leaves the choked branch sooner, because the branch turns over at a smaller fraction of the relieving pressure.", "A stiffer gas needs a larger area on the choked branch, because the ratio and the coefficient C move in the same direction.", "A stiffer gas carries a larger subcritical factor at any ratio, because F2 is the reciprocal of the critical ratio.", "A stiffer gas stays choked down to a lower outlet pressure, because the branch turns over at a smaller fraction of the relieving pressure."]'::jsonb, 3, 'The branch turns over where the outlet fraction passes the critical ratio, so a smaller critical ratio leaves more of the range choked. The ratio and C move in opposite directions across the same exponents.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 4, 'ORUBIRI states an isentropic exponent of 1.270000 and its outlet pressure works out at a fraction of 0.104258 of the relieving pressure. Which branch runs, and why?', '["Subcritical, because 0.104258 is below the critical ratio of 0.551208 the engine returns at that exponent.", "Critical, because 0.104258 is below the critical ratio of 0.551208 the engine returns at that exponent.", "Critical, because 0.104258 is below the measured 0.300000 at which the balanced bellows warning fires.", "Critical, because the stated back pressure of 35.000000 psig is below the atmospheric constant of 14.700000000000 psia."]'::jsonb, 1, 'At or below the critical ratio the flow is choked and the critical equation runs. The 0.300000 edge is where a chart Kb warning fires and decides no branch, and 35.000000 psig is above one atmosphere rather than below it.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 5, 'Walked as a fraction of the relieving pressure from 0.100000 to 0.551207, the required area stays at 2.223779 in2 on all six rows. What does that say?', '["The six rows are too close together for the engine to resolve, so the area is printed at the same six decimals throughout.", "The outlet pressure moves the area only through Kb, and Kb was held at 1.000000 across all six of those rows.", "In choked flow the throat is set by the upstream condition, so the area does not move with the outlet pressure at all.", "The engine holds the area at its value on the first row until the branch turns over, and recomputes it afterwards."]'::jsonb, 2, 'That flatness is the meaning of choked and it is live behaviour rather than a simplification. It holds at a Kb of 1.000000 and at a Kb of 0.720000 alike, since Kb divides an area that is itself unmoved by the outlet pressure.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 6, 'The two rows either side of the crossing sit at 0.551207 and 0.551209. What do the areas do across them?', '["The area steps from 2.223779 in2 to 2.658695 in2, so the branch change carries a visible discontinuity.", "The area is unchanged at 2.223779 in2, so the two branches agree exactly at the crossing.", "The area falls from 2.223779 in2 to 2.112125 in2, so the subcritical form gives the smaller answer at the crossing.", "The area steps from 2.223779 in2 to 2.224962 in2, so the branch changes without the answer jumping."]'::jsonb, 3, 'The two probes are placed either side of the measured critical ratio of 0.551208 so the size of the step is visible rather than asserted. The area 2.658695 in2 belongs to a fraction of 0.800000, much further up the subcritical branch.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 7, 'The same call is run at a Kb of 1.000000 and a Kb of 0.720000 on both branches. What happens?', '["On the critical branch the area moves from 2.223779 in2 to 3.088582 in2, and on the subcritical branch both calls give 2.658695041098 in2.", "On the critical branch both calls give 2.223779 in2, and on the subcritical branch the area moves from 2.658695 in2 to 3.088582 in2.", "Both branches move, since Kb divides the area wherever it is typed, and the two branches differ only in the size of the step it makes.", "Neither branch moves, since the engine ignores a typed Kb on both of them and attaches a warning saying so."]'::jsonb, 0, 'In critical flow Kb divides the area, so a smaller Kb demands a larger one. The subcritical form has no place for Kb at all, the two areas agree to twelve decimals, and the engine attaches a warning rather than leaving that to be discovered.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 8, 'Why can F2 not be tabulated the way the coefficient C can?', '["It is computed from the isentropic exponent and the relieving pressure together, so a chart of it needs two axes.", "It is computed from the isentropic exponent and the pressure ratio together, so a chart of it needs two axes.", "It is recomputed on every pass of an iteration, so no single value of it belongs to a case at all.", "It is a published fit rather than a closed form, and the coefficients of that fit are held for literature."]'::jsonb, 1, 'F2 is the one factor in this module that needs two inputs. It is a closed form checked by an oracle that integrates the subcritical nozzle flux, so nothing about it is held for literature.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 9, 'Walked from 0.600000 to 0.900000, F2 rises from 0.735763 to 0.939468 and the required area rises with it from 2.237461 in2 to 3.504623 in2. How should that pairing be read?', '["As cause and effect, because a larger F2 divides into a fixed numerator and a larger divisor leaves a larger area behind.", "As cause and effect, because F2 multiplies the area directly once the subcritical form is running.", "As two readings of one call, because the engine recomputes the coefficient C alongside F2 and the two corrections compound.", "As two readings of one call, because the differential across the valve shrinks as the outlet pressure climbs and moves the answer harder than the rising factor does."]'::jsonb, 3, 'Two things move at once. The subcritical form divides by the square root of the relieving pressure multiplied by the differential, and that differential collapses as the outlet pressure rises. C leaves the equation entirely above the critical ratio.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 10, 'Where did the subcritical leading constant of 735.000000000000 come from?', '["From the module source, where it is exported beside the coefficient C for inspection.", "From the published standard, quoted here because no arrangement of calls can reach it.", "From one subcritical area rearranged against its own stated inputs and the engine own F2.", "From the critical leading constant of 520.000000000000 scaled by the ratio of the two forms."]'::jsonb, 2, 'Nothing in this module exports it. Recovering it means arranging a call in which every other factor is one, which is why the figure is quoted as a measurement with the question that produced it named beside it.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 11, 'ORUBIRI runs at 68000.000000 lb/hr and no warning fires. Why not?', '["Its outlet fraction of 0.104258 is below the critical ratio of 0.551208, and a choked case never carries a warning of any kind.", "Its outlet fraction of 0.104258 is below the 0.300000 at which the chart Kb warning fires, and no other edge on this route is reached.", "Its typed Kb of 1.000000 changes nothing on this call, and the engine attaches a warning only where a typed factor was ignored on the branch that ran.", "Its required area of 2.223779 in2 sits inside the published orifice ladder, and a case that selects a letter without refusing carries no warning."]'::jsonb, 1, 'The bellows warning fires on a choked case above a measured outlet fraction of 0.300000, and a choked case above that fraction does carry it. A subcritical row at a fraction of 0.800000 and a Kb of 1.000000 carries no warning at all, and the ignored Kb notice is the separate one that belongs to that branch.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 12, 'Five gas rows are published for this route. What can the single row at a Kd of 0.900000, a Kb of 0.880000 and a Kc of 0.900000 check that the other four cannot?', '["That the three coefficients divide the area rather than multiplying it.", "That the branch decision is made on the outlet fraction rather than on the outlet pressure.", "That the coefficients are each validated as a fraction of an ideal on the way in.", "That a certified coefficient belongs to the valve rather than to the fluid it passes."]'::jsonb, 0, 'A case run at coefficients of one cannot tell the two arrangements apart, because one divided by one and one multiplied by one are the same number. That one row is a thin margin for an important property.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 13, 'Two of the five published gas rows share a flow of 80000.0000 lb/hr and a relieving pressure of 514.700000 psia, differing only in an outlet pressure of 300.000000 against 400.000000 psia. What does that pair establish?', '["That the branch decision itself is correct, since the pair straddles the crossing between the two forms.", "That the outlet pressure is read as an absolute figure, since a gauge reading would have put both rows on the critical branch.", "That the subcritical branch responds to the outlet pressure, with the areas at 2.334502 in2 and 2.693414 in2.", "That the published areas and the engine areas agree more closely on the critical branch than on the subcritical one."]'::jsonb, 2, 'Both rows are subcritical, so neither one tests the branch decision. The relative difference on this pair is 5.295e-4 against 1.061e-3 on the critical rows, which is the smaller figure rather than the larger.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 14, 'How does the validation oracle check the critical pressure ratio?', '["It evaluates the same closed form again in absolute SI units and compares the two answers digit for digit.", "It takes the argmax of the isentropic nozzle mass flux over the throat ratio by golden section search.", "It reads the ratio straight from the published table the standard prints against the isentropic exponent.", "It bisects the engine own branch flag and confirms that the crossing sits exactly where the ratio says it does."]'::jsonb, 1, 'The critical ratio is the ratio at which the flux through the throat is greatest, so searching for that maximum recovers it from a different construction. A gate that restates the formula under test validates nothing.'),
  ('relief', 'beginner', 'module', 'm02-gas-and-vapour', 15, 'Which two figures on a gas case are worked out from the same single input?', '["The coefficient C and the critical pressure ratio, both functions of the isentropic exponent alone.", "The critical pressure ratio and the outlet fraction, both dimensionless readings of the same two pressures.", "The factor F2 and the typed Kb, both of which belong to the form that runs above the critical ratio.", "The required area and the margin, both of them settled as soon as the load and the conditions are stated."]'::jsonb, 0, 'C rises with the exponent and the critical ratio falls with it, and the two are computed on every call from that one figure. The margin needs a published rung as well as an area, and Kb has no place in the subcritical form.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 1, 'Where does viscosity enter the liquid sizing route?', '["In a correction applied to the area equation, written Kv, which is a function of one Reynolds number.", "In the area equation itself, as a term beside the specific gravity and the differential across the valve.", "In the certified discharge coefficient Kd, which the manufacturer measures on the service the valve will see.", "In the leading constant of 38.000000000000, which carries the unit packaging of the whole equation."]'::jsonb, 0, 'The sizing equation has no viscosity in it. Kv sits in front of that equation and depends on a Reynolds number and nothing else, and Kd is a certified figure belonging to the hardware.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 2, 'AKASO returns an area of 1.839323 in2 with the viscosity left out and 1.867758 in2 with 85.000000 cp stated. What else does the viscous call report?', '["A Kv of 1.015459516779, a Reynolds number of 17412.317969, six passes, converged true and a residual of 0.000000000000.", "A Kv of 0.984776, a Reynolds number of 17546.394776, one pass, converged true and a residual of 0.000000000000.", "A Kv of 0.984776, a Reynolds number of 17412.317969, six passes, converged true and a residual of 0.000000000000.", "A Kv of 0.984776, a Reynolds number of 17412.317969, six passes, converged false and a residual it names."]'::jsonb, 2, 'The correction sits below one and the loop reports itself converged in six passes. The 1.015459516779 is the ratio of the two areas and 17546.394776 is the Reynolds number a single pass would have used.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 3, 'The digest prints 1.015459516779 for AKASO. What is that figure?', '["The ratio of the inviscid area to the viscous one.", "The ratio of the viscous area to the inviscid one.", "The ratio of the converged area to the one pass area.", "The reciprocal of the correction the loop settled on."]'::jsonb, 1, 'It is the viscous area over the inviscid one, and it is quoted only because the digest computes and prints it. The converged area over the one pass area is a separate printed ratio of 1.000083905751.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 4, 'A single pass through the liquid loop gives 1.867601 in2 at a Kv of 0.984858. What does the converged answer of 1.867758 in2 say about the shortcut?', '["On this case the loop moves the area by about one part in a hundred, which is enough to change the orifice letter the case selects.", "On this case the loop and the single pass agree exactly, so the iteration exists only for viscosities far above the one stated.", "On this case the single pass gives the larger area, so a hand calculation done that way is conservative for any liquid.", "On this case the loop moves the area by about one part in ten thousand, and the single pass remains an approximation to the correct construction."]'::jsonb, 3, 'The digest prints the ratio of the converged area to the one pass area as 1.000083905751. The single pass answer is the smaller of the two, and knowing the size of an approximation is not the same as being allowed to ignore it.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 5, 'At 1.000000 cp and at 5.000000 cp the engine returns the inviscid area of 1.839323 in2, although a Reynolds number was computed on both rows. Why?', '["Both rows sit above the Reynolds number of 196282.561354814417 at which the correction is held at one.", "Both rows sit below the Reynolds number of 196282.561354814417 at which the correction is held at one.", "Both viscosities are below the 50.000000 at which the engine stops evaluating the fit and returns the uncorrected area.", "Both rows converged on the first pass, and the engine returns the starting area whenever the loop takes a single pass."]'::jsonb, 0, 'Those two Reynolds numbers are 1491443.555990 and 298288.711198, both above the clamp. A stated viscosity that changes nothing there is the clamp doing its declared job.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 6, 'The unclamped fit is exported beside the clamped one. What does it show, and why does that matter?', '["It falls away from one and asymptotes to 0.993500000000, so a correction for viscous drag would remove capacity without limit.", "It rises through one and asymptotes to 1.006542523506, so a correction for viscous drag would add capacity if nothing held it.", "It reproduces the clamped fit exactly at every Reynolds number, so the clamp is a statement about the inputs rather than the output.", "It rises through one only below the clamp, so the two exports part company at the low Reynolds end of the range."]'::jsonb, 1, 'The asymptote is what the clamp is protecting against, and it stays inspectable because the raw fit is exported. The 0.993500000000 is the intercept term of the fit rather than an asymptote.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 7, 'Which of these is true of the three coefficients of the Kv fit?', '["The oracle derives all three of them from the definition of a Reynolds number in absolute SI units.", "They are pinned by the published liquid cases, one of which sits low enough on the range to check each one.", "Nothing in the package derives them, and the validation oracle shares the same three on purpose.", "They are computed together from the leading constant of 38.000000000000 and the Reynolds constant of 2800."]'::jsonb, 2, 'The fit is held for literature. What the oracle does check on this route is the Reynolds constant, derived from rho u D over mu in SI, and the leading constant of the area equation against the published SI form.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 8, 'At a Reynolds number of 10.000000 the steepest term of the fit is 0.850608 of the sum, and by 3000.000000 it is 0.001990. What does that table settle?', '["That the fit has a band it does real work in, and that outside that band its steepest coefficient could move a long way without changing an answer.", "That the fit is wrong outside that band, which is why the correction is clamped at one above a Reynolds number of 196282.561354814417.", "That the intercept term is the one worth checking, since it is the only term that changes with the Reynolds number at all.", "That a published case anywhere in the range exercises all three terms, since the three of them always sum to one divided by Kv."]'::jsonb, 0, 'The intercept sits at 0.993500 on every row, so it is the term that does not move. The clamp is a stated convention about the output rather than a statement that the fit is wrong, and a case at a high Reynolds number exercises the steepest term hardly at all.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 9, 'Why does the published liquid set include a row at a Reynolds number of 92.428866?', '["So that the clamp at one is exercised by at least one published case.", "So that the envelope warning below a Kv of 0.500000000000 is reached at least once.", "So that the Reynolds constant of 2800.000000000000 can be measured from a published row.", "So that the steepest term of the fit is worth something on at least one published case."]'::jsonb, 3, 'Read the term table at that end of the range and compare the fraction there with the fraction at the other rows. That row carries a Kv of 0.595745, which is above the warning edge, and the clamp acts at the opposite end of the range.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 10, 'Where does the liquid Reynolds constant of 2800.000000000000 come from, and what checks it?', '["It is recovered from one inviscid area at unit coefficients, and the oracle checks it against the published SI form of the area equation.", "It is recovered from the engine own returned Reynolds number rearranged against the area it belongs to, and the oracle derives it from rho u D over mu in SI.", "It is read from the module source, and the oracle pins it as behaviour because no independent derivation of it exists.", "It is recovered from three readings of the unclamped correction, and the oracle shares it with the engine on purpose."]'::jsonb, 1, 'The oracle takes the diameter as the square root of four times the area divided by pi, which arrives at the constant from the definition of a Reynolds number. The inviscid rearrangement is how the leading constant of 38.000000000000 was measured instead.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 11, 'The pass count runs 0 with no viscosity, 1 at 1.000000 cp and at 5.000000 cp, and 12 at 5000.000000 cp. What does a high pass count tell a reader?', '["That the loop is struggling to converge on that case, so the returned area should be read with the convergence flag against it.", "That the case sits outside the certified envelope, so the engine has attached its off envelope notice to the answer.", "That the correction is doing real work on that case, so a hand calculation stopped after one pass is furthest from the converged answer.", "That the area is changing between passes by more than the residual the loop reports, so the residual understates the movement."]'::jsonb, 2, 'Every row in that sweep is reported converged, so a high count is work rather than difficulty. The envelope notice is a separate warning that fires on the correction rather than on the pass count.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 12, 'Below what value of the correction does the engine attach its off envelope notice, and what does the notice change?', '["Below 0.500000000000, and it refuses the case rather than returning an area at all.", "Below 0.801154, the lowest correction the viscosity sweep reaches, and it changes nothing about the area.", "Below 0.993500000000, the intercept of the fit, and it holds the area at its value on the previous pass.", "Below 0.500000000000, and it changes nothing about the area, which the engine returns as usual."]'::jsonb, 3, 'The edge was found by walking the engine until the notice appeared. It is a notice rather than a refusal, and the 0.993500000000 is the intercept term of the fit rather than an edge of any kind.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 13, 'The viscosity is walked from 0.000000 to 5000.000000 cp on one liquid case. Which set of directions does that sweep show?', '["A lower Kv, a larger area, a lower Reynolds number and more passes as the liquid thickens.", "A lower Kv, a smaller area, a lower Reynolds number and more passes as the liquid thickens.", "A lower Kv, a larger area, a higher Reynolds number and fewer passes as the liquid thickens.", "A higher Kv, a larger area, a lower Reynolds number and more passes as the liquid thickens."]'::jsonb, 0, 'Not one of the four ever reverses across the sweep, and two rows leave three of them standing still where the clamp holds the correction at one. A viscous liquid is harder to push through an orifice, so the valve has to be larger to pass the same rate.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 14, 'With no viscosity stated at all, what does the liquid route return for the Reynolds number?', '["A zero, which is the figure the loop starts from before it takes its first pass.", "A very large number standing in for the inviscid limit of the fit.", "A null, because with no viscosity there is no Reynolds number to report.", "The value the clamp acts at, since the correction comes back at one."]'::jsonb, 2, 'The digest prints that field as absent on the inviscid row rather than as a figure. A caller doing arithmetic on it gets zero, which is a perfectly plausible looking Reynolds number, so the absence has to be handled as an absence.'),
  ('relief', 'beginner', 'module', 'm03-liquid', 15, 'AKASO states a Kd of 0.650000 while the gas and steam streams state 0.975000. What kind of figure is that?', '["A published chart factor, read off its chart against the liquid service condition and then typed in by the caller.", "The valve manufacturer own certified discharge coefficient, validated on the way in as a fraction of an ideal.", "A closed form the engine evaluates from the specific gravity and the differential.", "A published table entry that the oracle checks against its own SI statement."]'::jsonb, 1, 'A certified coefficient is measured on a real device on a test stand, and every coefficient is validated on the way in as above zero and no more than one. A liquid service figure and a vapour one are different quantities.'),
  ('relief', 'beginner', 'module', 'm04-steam', 1, 'What does the steam route need handed to it that the gas route also needs, and what can it do without?', '["It needs a flow, a relieving pressure and the coefficients, and it needs no outlet pressure, isentropic exponent or certified discharge coefficient.", "It needs a flow, a relieving pressure, a temperature and the coefficients, and it needs no molecular weight, compressibility or isentropic exponent.", "It needs a flow, a relieving pressure and a superheat factor, and it needs no certified coefficient, molecular weight or compressibility at all.", "It needs a flow, a relieving pressure and the coefficients, and it needs no molecular weight, compressibility, temperature or isentropic exponent."]'::jsonb, 3, 'Saturated steam at a stated pressure is a defined state, so the published equation folds the gas properties into one leading constant. The certified coefficient is stated on this route as on every other.'),
  ('relief', 'beginner', 'module', 'm04-steam', 2, 'TEBIDABA states 94000.0000 lb/hr at a set pressure of 1740.000000 psig with a 10.000000 percent allowance. What does the engine return?', '["A relieving pressure of 1928.700000 psia, a correction of 0.998342 and a required area of 1.144559 in2.", "A relieving pressure of 1928.700000 psia, a correction of 1.021727 and a required area of 0.949984 in2.", "A relieving pressure of 1928.700000 psig, a correction of 1.021727 and a required area of 1.287000 in2.", "A relieving pressure raised from the set pressure by the allowance alone, with the same correction and the same area."]'::jsonb, 1, 'The allowance is applied to the gauge set pressure and the atmospheric constant is added afterwards, which is what puts the relieving pressure in psia. The 1.287000 in2 is the J orifice this case selects rather than the area it needed, and 1.144559 in2 is the same case run superheated.'),
  ('relief', 'beginner', 'module', 'm04-steam', 3, 'The Napier correction is 1.0 up to a threshold and then does what?', '["It steps below one, stays below one to a crossing the engine derives and exports, and rises past one above that.", "It steps above one, stays above one to a crossing the engine derives and exports, and falls back through one above that.", "It slides smoothly below one from the threshold and returns through one at the top of the published range.", "It steps below one at the threshold and holds that value until the route refuses at the top of the published range."]'::jsonb, 0, 'Between the threshold and the crossing the correction sits below one, which makes the required area larger than the uncorrected equation would give. Above the crossing it rises for the rest of the published range.'),
  ('relief', 'beginner', 'module', 'm04-steam', 4, 'A millionth of a psi below the threshold the correction is 1.000000000000 and a millionth above it is 0.995677635301. What does that pair establish?', '["That the correction slides, since a change that small across a change that small is a smooth gradient.", "That the threshold was bisected wrongly, since a continuous fit cannot move by that much over that interval.", "That the correction steps rather than sliding, by -0.004322364699 across two millionths of a psi.", "That the required area steps by the same -0.004322364699, since the correction multiplies it directly."]'::jsonb, 2, 'A step matters more than its size suggests, because two cases a psi apart in relieving pressure get different valves with nothing in the inputs looking like a discontinuity. The area moves by the reciprocal of the step rather than by the step.'),
  ('relief', 'beginner', 'module', 'm04-steam', 5, 'Which relieving pressures on the TEBIDABA sweep carry a warning?', '["1600.000000, 1800.000000 and 2000.000000 psia, which are the rows where the correction has risen past one.", "3000.000000 and 3200.000000 psia, which are the rows approaching the top of the published range.", "1000.000000, 1400.000000 and 1500.000000 psia, which are the rows where the correction is exactly one.", "1520.000000, 1550.000000 and 1580.000000 psia, which are the rows between the threshold and the crossing."]'::jsonb, 3, 'The engine flags the interval where the correction is below one and the required area is therefore larger. Below the threshold the correction is exactly one and nothing is flagged, and above the crossing the correction behaves the way a correction is normally expected to.'),
  ('relief', 'beginner', 'module', 'm04-steam', 6, 'The crossing back through unity is reported twice, at 1580.310880829016 psia. Why is that worth printing twice?', '["Because one figure was bisected out of the returned correction and the other is the engine own exported constant, so the two are a real agreement.", "Because one figure belongs to the published fit and the other to the engine implementation of it, so the two are a tolerance.", "Because one figure is the crossing and the other is the top of the range, and on this route the two happen to coincide.", "Because one figure is measured at the TEBIDABA load and the other at unit coefficients, so the pair shows the load does not move it."]'::jsonb, 0, 'A derived constant and a bisection of the behaviour it is supposed to describe are two different routes to the same pressure. The top of the published range is a separate figure at 3200.000000000003 psia.'),
  ('relief', 'beginner', 'module', 'm04-steam', 7, 'What happens above 3200.000000000003 psia on the steam route?', '["The route refuses, because the required area has fallen below the smallest listed orifice.", "The route refuses, because the correction is published only that far.", "The route returns an area with a warning, because the fit is being extrapolated past its range.", "The route holds the correction at its value on the boundary and returns an area anyway."]'::jsonb, 1, 'That refusal is a stated limit rather than a numerical failure. Nothing breaks at that pressure, and the engine declines to extrapolate a published fit past where it was published.'),
  ('relief', 'beginner', 'module', 'm04-steam', 8, 'Below the threshold, at 1000.000000, 1400.000000 and 1500.000000 psia, the required area falls from 1.872044 in2 to 1.248029 in2 at one load. Why?', '["The correction rises with pressure across those three rows, and a larger correction divides the area down.", "The three rows sit at different loads, since a relieving pressure is only reached by changing the flow.", "A higher pressure pushes more mass through the same hole, so less hole is needed for the same flow.", "The leading constant of 51.500000000000 is scaled by the pressure, which shrinks the area as the pressure climbs."]'::jsonb, 2, 'The correction is exactly 1.000000 on all three rows, so nothing in that column confounds the reading. The leading constant is a constant and the load is the same 94000.0000 lb/hr on every row.'),
  ('relief', 'beginner', 'module', 'm04-steam', 9, 'Which of the two corrections on the steam route does the engine compute, and which does it take on trust?', '["It computes the superheat factor KSH from the pressure and takes the Napier correction as a typed chart value.", "It computes the Napier correction from the pressure and takes the superheat factor KSH as a typed table entry.", "It computes both of them, the first from the pressure and the second from the pressure and the temperature.", "It takes both of them as typed inputs, which is why the route carries two published references rather than one."]'::jsonb, 1, 'The Napier fit is checked against the standard own SI statement of it. Nothing in this package can derive a single entry of the superheat table, and the oracle cannot check it either.'),
  ('relief', 'beginner', 'module', 'm04-steam', 10, 'Run as a superheated service with a factor of 0.830000 typed in, the TEBIDABA area becomes 1.144559 in2 against the 0.949984 in2 the saturated case needed. What does that direction say?', '["A factor below one makes the required area smaller, because a factor is a credit against the uncorrected equation.", "A factor below one leaves the required area alone, because the superheat table is typed rather than computed.", "A factor below one makes the required area larger, because the Napier correction is recomputed at the superheated state.", "A factor below one makes the required area larger, because superheated steam is less dense and the same hole passes less mass."]'::jsonb, 3, 'The factor arrives as a number with no explanation attached, and a typed number is easy to enter the wrong way round, so the direction is worth holding onto. The Napier correction depends on the pressure alone.'),
  ('relief', 'beginner', 'module', 'm04-steam', 11, 'Two of the five published steam rows share a flow of 60000.0000 lb/hr and a relieving pressure of 314.700000 psia. What makes that a well built pair?', '["Only the flow differs, and both rows sit below the threshold where the other correction is exactly 1.000000.", "Only the typed superheat factor differs, and both rows sit inside the band where the other correction is below one.", "Only the typed superheat factor differs, and both rows sit below the threshold where the other correction is exactly 1.000000.", "Only the certified coefficient differs, and both rows sit above the crossing where the other correction is above one."]'::jsonb, 2, 'The published areas are 3.796612 in2 and 4.574231 in2, and a pair that moved two things at once could confirm an answer without testing either of them. What the pair cannot say anything about is the table the factor was copied from.'),
  ('relief', 'beginner', 'module', 'm04-steam', 12, 'Three of the five published steam rows have the Napier correction active. At which pressures?', '["2014.700000, 3100.000000 and 1550.000000 psia.", "2014.700000, 3100.000000 and 314.700000 psia.", "1928.700000, 3200.000000 and 1550.000000 psia.", "2014.700000, 1580.310880829016 and 1550.000000 psia."]'::jsonb, 0, 'The two rows at 314.700000 psia sit below the threshold with the correction at exactly 1.000000. The 1928.700000 psia is the TEBIDABA relieving pressure rather than a published row.'),
  ('relief', 'beginner', 'module', 'm04-steam', 13, 'Why is the published row at 1550.000000 psia more valuable than the others?', '["It sits at the threshold itself, which is the one pressure at which the size of the step can be measured across a row.", "It sits inside the band where the correction falls below one, which is the behaviour most people find surprising.", "It is the only row whose published correction and returned correction agree to every printed digit.", "It is the only row that carries a superheat factor away from 1.000000 as well as an active correction."]'::jsonb, 1, 'Its correction is 0.998366 published against 0.998342 returned, which is the fit evaluated twice rather than a disagreement. A published set with no row in that band would leave the most contestable part of the route untested.'),
  ('relief', 'beginner', 'module', 'm04-steam', 14, 'The steam leading constant of 51.500000000000 was recovered how, and what checks it?', '["From one steam area above the Napier crossing at unit coefficients, and the oracle checks it against the published SI form.", "From the ratio of two steam areas at the same load and different pressures, and the oracle pins it as behaviour.", "From one steam area below the Napier threshold at unit coefficients, and the oracle checks it against the published SI form.", "From the exported crossing of 1580.310880829016 psia divided by the threshold, and the oracle derives it from the fit."]'::jsonb, 2, 'Taking the area below the threshold is what makes the correction exactly one, so nothing but the leading constant is left in the arrangement. The oracle also checks the fit against the standard own SI statement of Napier, so two published routes meet on this equation.'),
  ('relief', 'beginner', 'module', 'm04-steam', 15, 'What do the published steam rows leave untested?', '["The refusal past the top of the range and the step at the threshold itself.", "The band where the correction sits below one and the refusal past the top of the range.", "The superheated case and the step at the threshold, neither of which any row reaches.", "The agreement between the published and the returned correction."]'::jsonb, 0, 'The set straddles the threshold, puts a row inside the awkward band, reaches close to the top of the range and includes one superheated case. The two behaviours it never visits are covered by bisecting the engine instead.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 1, 'The engine own exported orifice table carries fourteen rows. What does the column of ratios between neighbouring areas show?', '["That the ladder is geometric, since every step is close enough to the same figure for the spread to be rounding.", "That the ladder is not geometric, since the steps run from 1.205556 up to 1.781818 in no tidy direction.", "That the ladder is geometric above the J orifice, since the steps settle once the areas pass 1.287000 in2.", "That the ladder is not geometric, since the steps fall steadily from 1.781818 at the bottom to 1.205556 at the top."]'::jsonb, 1, 'The ratios are 1.781818, 1.566327, 1.638436, 1.560636, 1.639490, 1.428127, 1.552231, 1.261830, 1.205556, 1.470046, 1.731975, 1.447964 and 1.625000 going up. The smallest sits between M and N in the middle of the ladder and the largest between the two smallest orifices.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 2, 'Which letters does the published ladder skip between D and T?', '["I, O and U.", "I, S and V.", "I, O and S.", "O, S and X."]'::jsonb, 2, 'Read the exported table top to bottom: D, E, F, G, H, J, K, L, M, N, P, Q, R and T. Fourteen letters are printed across a span of seventeen, and the three absent ones are what is left. Why the published table leaves them out is not something the engine or the digest says.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 3, 'State the selection rule this engine applies.', '["Return the smallest listed orifice whose area is at or above the required area.", "Return the smallest listed orifice strictly above the required area.", "Return the listed orifice closest to the required area either way.", "Return the smallest listed orifice at or above the area times a margin."]'::jsonb, 0, 'At or above is the whole of it, with no margin applied on the way. The boundary rows are what distinguish this rule from the strictly above one, because the two agree everywhere else.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 4, 'A required area of 0.110000 in2 takes D and a required area of 0.110001 in2 takes E. What do those two rows prove?', '["That the ladder is walked from the top down rather than from the bottom up.", "That the engine rounds a required area to the precision of the published table.", "That a required area below the smallest listed orifice is refused rather than served.", "That the comparison is at or above rather than strictly above."]'::jsonb, 3, 'A boundary case is the only case that can distinguish two rules which agree everywhere else. The first row lands exactly on the smallest listed area and takes it, with a margin of exactly 1.000000.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 5, 'What does a required area of 0.050000 in2 select, and with what margin?', '["D at 0.110000 in2, with a margin of 1.000000.", "D at 0.110000 in2, with a margin of 2.200000.", "Nothing, since the required area is below the smallest listed orifice.", "E at 0.196000 in2, with a margin of 1.781818."]'::jsonb, 1, 'The smallest listed orifice is still the smallest one at or above the requirement, so the engine serves it. A very small required area therefore buys a lot of spare capacity, which is a property of the published ladder.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 6, 'How is the margin the engine returns defined?', '["The purchased orifice area divided by the required area.", "The required area divided by the purchased orifice area.", "The purchased orifice area less the required area, in in2.", "The ratio of the purchased orifice area to the rung below it."]'::jsonb, 0, 'Every row landing exactly on a listed area comes back at 1.000000, which is the same statement read a second way. The ratio to the rung below is the ladder column rather than the margin on a selection.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 7, 'The three streams of this tier end at 2.223779 in2, 1.867758 in2 and 0.949984 in2. What do they select?', '["L, K and J, at margins of 1.282951, 1.527500 and 1.354759.", "L, L and J, at margins of 1.282951, 1.354759 and 1.527500.", "L, L and J, at margins of 1.282951, 1.527500 and 1.354759.", "L, L and K, at margins of 1.282951, 1.527500 and 1.838000."]'::jsonb, 2, 'Read each required area up to the first rung at or above it, then divide that rung by it. The 1.838000 is the K orifice area rather than a margin, and the two margins belong to the streams in the order the areas were given.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 8, 'Two cases with identical engineering behind them come back with very different margins. What does that say about a margin?', '["That one of the two cases was sized on a load that was not the governing one.", "That the certified discharge coefficients on the two cases differ, since a margin carries Kd.", "That a margin is a design allowance, and the two cases were allowed different accumulations.", "That it is an artefact of where a required area fell between two rungs."]'::jsonb, 3, 'A margin is not a safety factor and not a measure of how conservative the sizing was. That is why nothing graded in this course is a margin or an orifice letter.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 9, 'What does the validation suite check about the orifice table, and why can it not check more?', '["It checks the selection behaviour, because nothing in this package derives any of the fourteen published areas.", "It checks each of the fourteen areas against a standard bore, because a published area is a geometry.", "It checks the ratios between the rungs, because those are the only figures the engine computes here.", "It checks the margins the selection returns, because a margin is derived from two areas the engine holds."]'::jsonb, 0, 'Behaviour is checkable where the numbers are not: the smallest orifice at or above the requirement, a required area exactly equal to a listed one, and the refusal past the largest. The ratios and the margins are arithmetic on figures that are themselves typed.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 10, 'A required area of 26.000001 in2 is handed to the selection. What comes back?', '["A refusal naming the required area and the T orifice, with the margin that a single T would have left.", "A refusal naming the required area and the T orifice, with a second key carrying a whole number of valves.", "The T orifice with a margin below one, since the largest listed orifice is the best the ladder can do.", "A refusal naming the required area alone, since the number of valves depends on a spacing the engine is never told."]'::jsonb, 1, 'The second key is `multipleOfT`, read off the returned object rather than listed. Returning the largest orifice with a margin below one would be an answer that looks like an answer and is not.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 11, 'At 79.000000 in2 the refusal carries 4 and at 105.000000 in2 it carries 5. What is that figure?', '["How many rungs above the largest orifice it sits.", "How many square inches are left over after the count.", "How many times the area exceeds the largest orifice.", "How many of the largest orifice the required area needs."]'::jsonb, 3, 'It turns a dead end into the beginning of a design. A caller that reads only the `error` string throws that figure away, which is why the key has a name worth knowing.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 12, 'The refusal at 26.000100 in2 reads: required area 26.0001 in2 exceeds a T orifice (26 in2): use multiple valves. What is the point of the figure inside the message?', '["The message carries the required area rounded to the precision of the published table it failed against.", "The message carries the area of the largest orifice, so a caller can work out the shortfall from the text.", "The message carries the figure that made it true, so the statement and its evidence sit on the same line.", "The message carries the figure the caller typed, so a caller can see what was lost on the way in."]'::jsonb, 2, 'A refusal reading only that the area is too large would leave a user guessing which of their inputs the engine had actually received. The required area appears in the text to eight significant figures.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 13, 'A required area of 0.500000 in2 takes G at 0.503000 in2 with a margin of 1.006000. How should that be read?', '["As the honest answer to the question that was asked, with almost no spare area over the requirement.", "As a case that should be rounded up a rung, since a margin that close to one is outside the ladder intent.", "As evidence that the comparison is strictly above, since the required area and the listed area differ.", "As a case the engine would have refused had the required area been any larger at all."]'::jsonb, 0, 'Nothing is wrong with it. There is a difference between a valve that just passes and a valve that passes, and reading that difference is the caller job rather than the engine one.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 14, 'What shape does a selection call return when it succeeds, and when it refuses?', '["An object on a success and a bare NaN on a refusal, which is the contract the seven number returning exports keep.", "An object either way, carrying the letter and the margin on a success and the same fields with the letter left empty on a refusal.", "An object either way, carrying the letter, the areas and the margin on a success and an `error` string with the valve count on a refusal.", "An object on a success and a thrown error on a refusal, which is why a caller has to handle two shapes on this route."]'::jsonb, 2, 'There is no partial answer hiding beside the refusal. A bare number returning NaN is the contract of a different set of exports, and nothing in this module throws.'),
  ('relief', 'beginner', 'module', 'm05-from-an-area-to-a-letter', 15, 'Why is a refusal past the largest orifice not a failure of the tool?', '["Because the ladder can be extended by the caller, and the engine is waiting to be handed a fifteenth row.", "Because one valve of a standard size will not do that job, which is a real engineering answer.", "Because a required area that large is usually a bad input.", "Because the refusal is advisory and a caller may ignore it."]'::jsonb, 1, 'The engine declining to invent a fifteenth orifice is the tool being correct about the limits of the table it was given, and it hands back the valve count so the answer can be acted on.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Three relief cases on one train are gathered on one page, one gas, one liquid and one steam. What is the first thing that table teaches?', '["That the three cases can be ranked against each other by load, which is how the governing case on a train is chosen.", "That the three required areas stand in a relationship this engine works out for itself and then prints as a ratio.", "That three different fluids and three different published equations produce one identical shape of answer.", "That the three cases protect one vessel, so exactly one of them is the size that vessel is built to."]'::jsonb, 2, 'A load and a set of conditions arrive, a relieving pressure is worked out, one factor is computed and one is typed, a coefficient is stated, and out comes an area, a letter and a margin. The digest states only that these are three relief cases on one train, and it ranks nothing among them.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which pairing of a computed factor with a typed one is correct?', '["Gas has Kb computed and a critical ratio typed, liquid has Kw computed and Kv typed, steam has KSH computed and KN typed.", "Gas has a critical ratio computed and Kb typed, liquid has Kv computed and Kw typed, steam has KN computed and KSH typed.", "Gas has a critical ratio computed and Kc typed, liquid has Kv computed and Kd typed, steam has KN computed and Kb typed.", "Gas has a critical ratio computed and Kb typed, liquid has Kw computed and Kv typed, steam has KN computed and KSH typed."]'::jsonb, 1, 'Each route carries exactly one correction the engine derives and exactly one it takes on trust. Kc and Kd are stated coefficients on every route rather than the typed chart factor of any one of them.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 3, 'On the three streams the computed factors come back as 0.551208, 0.984776 and 1.021727. Which is which?', '["0.551208 is the gas back pressure ratio, 0.984776 the liquid Kw and 1.021727 the steam KSH.", "0.551208 is the liquid Kv, 0.984776 the steam KN and 1.021727 the gas critical ratio.", "0.551208 is the gas critical ratio, 0.984776 the steam KN and 1.021727 the liquid Kv.", "0.551208 is the gas critical ratio, 0.984776 the liquid Kv and 1.021727 the steam KN."]'::jsonb, 3, 'The gas back pressure ratio on that stream is 0.104258 rather than 0.551208, and Kw and KSH are the typed factors, both stated at 1.000000. A correction above one shrinks an area and a correction below one grows it.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Why is the relieving pressure on the liquid column printed in psig while the other two are printed in psia?', '["Because the liquid equation works on a differential, which is indifferent to the datum.", "Because the liquid route is the only one whose set pressure is stated in gauge.", "Because a liquid relieving pressure is always below one atmosphere absolute anyway.", "Because the liquid route applies the atmospheric constant after the correction rather than before it."]'::jsonb, 0, 'Every set pressure in this tier is stated in gauge. The difference is what the route needs afterwards: a mass flux through a throat needs an absolute upstream pressure, and a pressure drop does not.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What can be said about the three loads of 68000.0000 lb/hr, 860.0000 gpm and 94000.0000 lb/hr?', '["They can be ranked, since the steam load is the largest of the three and is therefore the governing case on the train.", "They can be compared once the liquid rate has been converted, using the specific gravity that the case already states.", "They are not comparable with each other, because a volumetric rate and a mass flow are different quantities.", "They are three readings of one load, taken at the three points on the train where it is measured."]'::jsonb, 2, 'The three columns cannot be ranked by load and nothing in the digest offers a conversion between them. The required areas are comparable, because they are the same quantity in the same unit.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Two of the three streams end at the L orifice from required areas of 2.223779 in2 and 1.867758 in2. What does that show?', '["The ladder at work, since there is nothing between K and L to buy.", "A coincidence about the plant, since two unrelated cases rarely need the same valve.", "That the two cases carry the same margin, since they select the same purchased area.", "That the liquid area was rounded up to the gas one before the selection was made."]'::jsonb, 0, 'The purchased area is 2.853000 in2 on both, and the rung under it at 1.838000 in2 is too small for either. Nothing about the plant put them together and nothing about the two cases is alike.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Which list is entirely computed by this engine?', '["The coefficient C from the exponent, the critical ratio from the exponent, F2 from the exponent and the ratio, Kv from the Reynolds number, and Kb from the ratio.", "The coefficient C from the exponent, the critical ratio from the exponent, F2 from the exponent and the ratio, Kv from the Reynolds number, and KN from the pressure.", "The coefficient C from the exponent, the critical ratio from the exponent, Kw from the differential, Kv from the Reynolds number, and KN from the pressure.", "The coefficient C from the exponent, KSH from the temperature, F2 from the exponent and the ratio, Kv from the Reynolds number, and KN from the pressure."]'::jsonb, 1, 'Take the three wrong lists one at a time. Kb is read against a back pressure ratio on a chart rather than worked out from one, Kw is read the same way for liquid, and KSH is a table entry against a superheat state rather than a function of a temperature. None of the three is evaluated anywhere in this package.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What kind of number is Kd, and how is it treated?', '["A published chart factor, always typed, read off its chart exactly as Kb and Kw are read.", "A closed form the engine evaluates from the fluid and the branch, reported on the return beside the area.", "A default of the engine, used as it stands, because a certified figure is a property of the standard rather than the device.", "The valve manufacturer own certified discharge coefficient, always stated, with the engine defaults standing in as placeholders for it."]'::jsonb, 3, 'It is measured on a real device on a test stand, which is why this course states it on every stream. The gas and steam streams state 0.975000 and the liquid stream states 0.650000.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What does the engine do with a coefficient handed to it that is above one?', '["It refuses it, since a certified figure has to be above zero and no more than one to be usable.", "It clamps it at one, the way the viscosity correction is clamped at one.", "It uses it and attaches a warning, because a coefficient above one is unusual rather than impossible.", "It uses it, because a coefficient above one is meaningful on the subcritical branch."]'::jsonb, 0, 'A certified coefficient is a fraction of an ideal, above zero and no more than one, and a value outside that range is refused rather than quietly used. The clamp at one belongs to the viscosity correction rather than to a coefficient.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A reader is handed an answer they doubt. Why does sorting the numbers into computed ones and typed ones change what they go and look at?', '["Because a computed factor can be checked against the published chart it came from, while a typed one has no reference anywhere in the package.", "Because a typed factor is always the larger source of error, so the investigation starts there and usually ends there.", "Because a computed factor is wrong only if its inputs or the implementation are, and both of those are checkable here, while a typed one can be read at the wrong condition or transcribed with two digits swapped.", "Because a computed factor is validated by a published case, while a typed factor is validated by the suite pinning it as behaviour."]'::jsonb, 2, 'Nothing in this engine can see a chart read at the wrong condition. The typed factors have their references named, and a published case on a route with a typed factor confirms the arithmetic around it rather than the table itself.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 11, 'In the walk this tier teaches, when is the atmospheric constant added?', '["Only where the route works on a differential across the valve, which in this tier is the liquid route.", "Only where the route works in absolute pressures, which is the gas route and the steam route.", "On every route, because a relieving pressure is an absolute pressure by the definition this course uses.", "On no route, because the engine adds it internally wherever it is needed."]'::jsonb, 1, 'The liquid route takes its two pressures in gauge and works on their difference, so the constant never enters it. Adding it there is how a liquid answer goes wrong by about one atmosphere.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 12, 'On a steam case the walk says to read the correction the engine returned rather than assuming it from the pressure. Why?', '["Because it steps at its published threshold and sits below one for an interval above that.", "Because it depends on the superheat factor as well, which is typed rather than computed.", "Because it is recomputed on every pass of the loop, so only the returned value is final.", "Because it is held for literature, so the returned figure is the only statement of it the package makes."]'::jsonb, 0, 'The correction is a closed form checked against the standard own SI statement, and nothing about it iterates. What makes it unassumable is the step and the interval below one.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What changes at the Professional tier?', '["The orifice table stops being typed, because the Professional tier derives the fourteen areas.", "The branch decision stops being read from a ratio, because the fire case is always choked.", "The certified coefficient stops being stated, because a fire case uses a published default.", "The load stops being an input, because the fire case computes its own from geometry."]'::jsonb, 3, 'It starts with the wetted area of a vessel, takes that through a duty and a latent heat to a load, and runs the chain to an orifice letter with no load typed in anywhere. The table stays typed and the coefficient stays stated.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which two things does this tier teach and never grade, and for what reason?', '["The critical ratio and the orifice letter, because one is decided by an input the caller states and the other by a published table.", "The viscosity fit and the orifice letter, because one is an empirical fit the package cannot derive and the other a published table it can only check as behaviour.", "The viscosity fit and the Napier correction, because both are published fits that the validation oracle shares with the engine.", "The superheat factor and the critical pressure ratio, because both are published table entries the package cannot derive."]'::jsonb, 1, 'Grading a figure nobody in the package can derive would be grading a reader copy of a standard. The critical ratio and the Napier correction are both computed and both checked by an independent derivation.'),
  ('relief', 'beginner', 'module', 'm06-the-associate-reading', 15, 'A learner changes an outlet pressure on a gas case and the required area does not move. What should they check first?', '["The units, because a gauge outlet pressure fed to the gas route is wrong by about one whole atmosphere every time.", "The typed Kb, because the engine ignores it and attaches a warning whenever the outlet pressure moves.", "The branch, since a case below its critical ratio is choked and its area is fixed by the upstream condition.", "The convergence report, because an unfinished loop returns the area it started from."]'::jsonb, 2, 'That flatness is correct behaviour rather than a broken tool. The ignored Kb belongs to the subcritical branch and the convergence report belongs to the liquid route.'),
  ('relief', 'beginner', 'final', null, 1, 'A sizing sheet carries 2.223779 in2 and 2.853000 in2 for one gas case. What are they?', '["The area at a typed Kb of 1.000000 and the area at a typed Kb of 0.720000.", "The area on the choked branch and the area on the subcritical branch.", "The area the case demands and the area of the orifice actually purchased.", "The area before the certified coefficient is applied and the area after it."]'::jsonb, 2, 'The second figure is a rung of the published ladder, which is why it carries three decimals of its own. The pair divides to the margin of 1.282951 that the selection returns.'),
  ('relief', 'beginner', 'final', null, 2, 'Which figure on that same gas case is the one a header modification could invalidate?', '["None of them while the case is choked, because the required area does not move with the outlet pressure there.", "The required area, because the outlet pressure enters the critical form through Kb and it is the header that sets that pressure.", "The margin, because a header modification moves the purchased area rather than the required one.", "The critical ratio, because it is worked out from the outlet pressure and the relieving pressure together."]'::jsonb, 0, 'The critical ratio is a function of the isentropic exponent alone, and the purchased area is a rung of a published table. Once a case is subcritical the outlet pressure does become part of the sizing answer.'),
  ('relief', 'beginner', 'final', null, 3, 'One case reports 1.839323 in2 and another 1.867758 in2 for the same liquid stream. What separates them?', '["The certified coefficient, stated at 0.975000 in the first call and 0.650000 in the second.", "The datum, with the first call working in absolute pressures and the second in gauge.", "The loop, with the first call stopped after one pass and the second run to convergence.", "The viscosity, left out of the first call and stated at 85.000000 cp in the second."]'::jsonb, 3, 'The inviscid call returns a correction of 1.000000 with no Reynolds number and no passes at all. A single pass on the same stated viscosity gives 1.867601 in2, which is a third figure again.'),
  ('relief', 'beginner', 'final', null, 4, 'A reader is shown 0.104258 and 0.551208 on one gas case. What are they, and what does the pair decide?', '["The critical pressure ratio and the outlet fraction, and their comparison decides whether the bellows warning fires.", "The outlet pressure as a fraction of the relieving pressure and the critical pressure ratio, and their comparison decides the branch.", "The outlet fraction and the measured edge at which a chart Kb is needed, and their comparison decides the branch.", "Two readings of the outlet fraction, one before the atmospheric constant is added and one after it."]'::jsonb, 1, 'The measured edge at which the chart Kb warning fires is 0.300000, a separate figure again. The critical ratio comes from the isentropic exponent and the outlet fraction comes from two pressures.'),
  ('relief', 'beginner', 'final', null, 5, 'Four figures on a steam case read 1928.700000, 1.021727, 0.949984 and 1.287000. Which one is the correction this route applies?', '["1.021727, the correction the engine worked out from the relieving pressure.", "1928.700000, the relieving pressure the engine worked out from the stated set pressure.", "0.949984, the required area the engine worked out from the load and the pressure.", "1.287000, the orifice area the engine returned from its own exported table."]'::jsonb, 0, 'The relieving pressure and the required area are both worked out too, but neither is a correction, and the orifice area is a published table entry. The correction on this route is the one figure that reads dimensionless and near one.'),
  ('relief', 'beginner', 'final', null, 6, 'A gas case comes back critical, at a required area of 2.223779 in2 and a margin of 1.282951. Which of those readings move if the caller types a different Kb?', '["Neither of them, since the engine attaches a warning and leaves a typed Kb out of the answer.", "The required area alone, since a margin is fixed by the rung the selection landed on.", "Both the required area and the margin, since Kb divides the area on the choked branch.", "The margin alone, since Kb enters after the area has been worked out and before the letter."]'::jsonb, 2, 'At a Kb of 0.720000 the same case needs 3.088582 in2, which is a different rung and a different margin again. A typed Kb is dropped only on the branch that has no place for it.'),
  ('relief', 'beginner', 'final', null, 7, 'Three margins on one train read 1.282951, 1.527500 and 1.354759. What do they tell a reader about the three cases?', '["That the second case was sized most conservatively of the three, since it carries the largest spare area over its own requirement.", "Almost nothing about the cases, since a margin records where a required area fell between two rungs of a published ladder.", "That the three cases were sized at different overpressure allowances, since a margin carries the allowance through.", "That the first case is closest to needing a larger valve, since a margin is a distance from the rung above."]'::jsonb, 1, 'Two cases with identical engineering behind them can end up with very different margins. Nothing graded in this course is a margin or an orifice letter, for that reason.'),
  ('relief', 'beginner', 'final', null, 8, 'Two selections come back at a margin of exactly 1.000000, one from a required area of 2.853000 in2 and one from 26.000000 in2. What do those two rows share?', '["Each required area sits a millionth of a square inch below a listed area on the ladder, which is what puts the margin at one.", "Each required area is the largest figure the rung above it can serve, so the margin comes out at one by arithmetic.", "Each was rounded to the three decimals the published table carries before the comparison was made.", "Each required area is exactly a listed orifice area, and the rule takes that orifice rather than the next one up."]'::jsonb, 3, 'A margin of exactly 1.000000 is the same statement as landing on a rung, read a second way. Such a case has no spare area at all over its requirement, and there is a difference between a valve that just passes and a valve that passes.'),
  ('relief', 'beginner', 'final', null, 9, 'One liquid reading is 0.984776 and another on the same stream is 0.984858. What separates them?', '["The first is the correction at the stated viscosity and the second is the correction at the clamp itself.", "The first is the correction the loop converged on and the second is what a single pass would have used.", "The first is the correction this engine returned and the second is the correction the validation oracle derived.", "The first is the correction on the converged area and the second the correction on the inviscid one."]'::jsonb, 1, 'Each figure carries its own Reynolds number, 17546.394776 for the shortcut and 17412.317969 for the loop. The shortcut is what a hand calculation usually does, and the digest prints the ratio between the two areas they imply.'),
  ('relief', 'beginner', 'final', null, 10, 'Which pair below is a computed figure standing beside the typed figure on the same route?', '["KN 1.021727 beside KSH 1.000000.", "Kv 0.984776 beside Kd 0.650000.", "The critical ratio 0.551208 beside Kc 1.000000.", "F2 0.875668 beside the outlet fraction 0.800000."]'::jsonb, 0, 'A stated coefficient is a third kind of figure again, and an outlet fraction is an input rather than a factor of either kind. The pairing asked for here is the one the steam route carries.'),
  ('relief', 'beginner', 'final', null, 11, 'The engine computes the exact circular segment and the terminal velocity balance, and types the API 526 table. What decides which treatment a quantity gets?', '["Whether a published case reaches it, since anything a golden checks is computed and anything no golden reaches is typed.", "Whether it carries units, since a unit bearing quantity has to be computed for the unit packaging to be checked.", "Whether it changes between cases, since a figure that moves with the fluid is computed and a fixed one is typed.", "Whether the package can state a closed form for it, since everything derivable is derived and everything published as a chart or a table arrives as an input."]'::jsonb, 3, 'The distinction is about where a number comes from. A chart value is typed even though it very much depends on the service, and the leading constants are computed even though they are fixed.'),
  ('relief', 'beginner', 'final', null, 12, 'Where does a figure that the module never exports come from in this course?', '["From the module source, read directly, since a constant in the source is the value in use by definition.", "From a call arranged so that its answer is that constant and nothing else, with the arrangement named beside the figure.", "From the published standard, since a leading constant is a property of the unit system rather than of an engine.", "From a fit to several returned answers, since one call can never isolate a constant hidden inside an equation."]'::jsonb, 1, 'Reading the source and reading the behaviour are two different claims, and only the second one catches a name attached to a different number. Three separate arrangements agree on the atmospheric constant of 14.700000000000 psia.'),
  ('relief', 'beginner', 'final', null, 13, 'The digest recovers only three of the four published Napier coefficients. Why?', '["Because the fourth is the threshold pressure, which is a published boundary rather than a coefficient.", "Because the fourth is only active above the exported crossing, where the published range has ended.", "Because a ratio of two lines is unchanged when all four of its coefficients are scaled together.", "Because the fourth cancels against the leading constant of 51.500000000000 in every arrangement."]'::jsonb, 2, 'Three pressures above the threshold solve the ratio of two lines, and the published quartet is one scaling of the three figures that solve. A threshold is a separate object again, and it was bisected rather than solved for.'),
  ('relief', 'beginner', 'final', null, 14, 'Which of these makes the engine refuse rather than warn?', '["A relieving pressure past the top of the published Napier range.", "An outlet fraction above 0.300000 on the gas route.", "A viscosity correction below 0.500000000000 on the liquid route.", "A latent heat below 50.000000000000 on the fire route."]'::jsonb, 0, 'The other three attach a notice to an answer the engine still returns, and only the steam route stops answering. A notice leaves a figure to act on and a refusal leaves none, so the two are read quite differently.'),
  ('relief', 'beginner', 'final', null, 15, 'A typed Kb of 0.720000 is handed to a subcritical gas case. What happens?', '["The area grows in proportion, since Kb divides the area on both branches of this route.", "The call refuses, since a typed factor that the running branch has no place for is an input error.", "The area is unchanged and nothing is said, since a factor with no place in the running form is silently dropped.", "The area is what it would have been at a Kb of 1.000000, to twelve decimals, and the engine attaches a warning saying the typed figure was ignored."]'::jsonb, 3, 'Both subcritical calls return 2.658695041098 in2. That is correct behaviour rather than a defect, because the standard uses F2 there, and the engine says so rather than leaving it to be discovered.'),
  ('relief', 'beginner', 'final', null, 16, 'Three corrections in this tier read 0.551208, 0.984776 and 1.021727. Which of the three can come back above one?', '["Only the liquid correction, since the raw fit it comes from asymptotes above one at a high Reynolds number.", "Only the steam correction, since the critical ratio is below one across the whole range the standard covers and the liquid one is held at one by its clamp.", "The steam correction and the liquid one, since both are corrections rather than ratios of two pressures.", "None of the three, since a correction above one would let a valve pass more than its certified rate."]'::jsonb, 1, 'The steam correction reaches 1.190866 at the top of its published range. The raw liquid fit does rise above one, which is exactly what the clamp is there to stop reaching an answer.'),
  ('relief', 'beginner', 'final', null, 17, 'A liquid call comes back with an area and three further fields about its loop. What are they for?', '["They say how many passes it took, whether it converged and what residual it stopped on, so an unfinished answer cannot be read as a finished one.", "They say how many passes it took, how far the area moved on the last pass and what the error bar on the area is.", "They say how many passes it took, whether the correction was clamped and whether the case is inside the certified envelope.", "They say how many passes it took, whether the area is above the smallest listed orifice and which letter it selected."]'::jsonb, 0, 'An iterative answer is right, wrong, or unfinished, and the third state is the one that ships by accident. The residual is a statement about the loop rather than an error bar on the valve.'),
  ('relief', 'beginner', 'final', null, 18, 'Which figure below was found by walking the engine until its behaviour changed, rather than by arranging a call around it?', '["The atmospheric constant of 14.700000000000 psia that every relieving pressure in the tier is built with.", "The liquid Reynolds constant of 2800.000000000000 that sits inside the Reynolds relation itself.", "The leading constant of 38.000000000000 in the liquid area equation.", "The outlet fraction of 0.300000000000 above which the chart Kb warning fires."]'::jsonb, 3, 'The other three are leading constants, recovered by arranging a call in which every other factor is one. An edge has no such arrangement, so it is bracketed and then narrowed until the behaviour turns over.'),
  ('relief', 'beginner', 'final', null, 19, 'Which correction below makes a required area LARGER when it sits below one?', '["Only Kv on the liquid route, since the other two multiply the area instead.", "All three of Kv on the liquid route, KN on the steam route and KSH on the steam route.", "Only KN on the steam route, since it is the one correction that is allowed below one.", "Only KSH on the steam route, since a typed factor enters the equation the other way round."]'::jsonb, 1, 'A correction below one divides into the area on each of those three routes. Kv is clamped so it never rises above one, KN sits below one between its threshold and its crossing, and a superheated KSH of 0.830000 takes an area from 0.949984 in2 to 1.144559 in2.'),
  ('relief', 'beginner', 'final', null, 20, 'Between the Napier threshold and the exported crossing, a relief case gets a bigger valve because a pressure rose. Why does the engine say so rather than leave it to be found?', '["Because a valve growing as a pressure rises is behaviour a user would otherwise read as a fault.", "Because the correction in that interval is outside the range the published fit covers.", "Because the area in that interval is computed from the threshold rather than from the stated pressure.", "Because the two published boundaries are pinned as behaviour rather than derived."]'::jsonb, 0, 'The engine notice states that the correction is below one across the interval, that the area is therefore larger, and that it steps at one boundary and returns through one at the other. The fit inside the interval is checked against the standard own SI statement.'),
  ('relief', 'beginner', 'final', null, 21, 'The viscosity correction is clamped at one. What is that clamp protecting against?', '["A correction dividing by a number near zero, which is what the raw fit does at the low Reynolds end.", "A published case landing above the range the three coefficients were fitted in and going unnoticed.", "A correction for viscous drag adding capacity to a valve, which is what the raw fit does as it asymptotes to 1.006542523506.", "A Reynolds number computed from an area that the same correction is still moving between passes."]'::jsonb, 2, 'The raw fit is exported so the asymptote stays inspectable, and the clamp is a stated convention of this engine rather than something derived. At the low Reynolds end the correction is small rather than large.'),
  ('relief', 'beginner', 'final', null, 22, 'What is the whole meaning of choked, read off a required area column?', '["The area is set by the upstream condition, so it is identical across every outlet fraction below the critical ratio.", "The area is set by the outlet condition, so it moves smoothly with that pressure until the critical ratio is reached.", "The area is the largest figure the case can demand of a valve, so every subcritical answer on the sweep sits below it.", "The area is computed from a different leading constant, so the two branches cannot be compared."]'::jsonb, 0, 'The subcritical areas sit ABOVE the choked one on this case, running from 2.224962 in2 upwards. The two forms do carry different leading constants, but that is not what the flatness says.'),
  ('relief', 'beginner', 'final', null, 23, 'The crossing is probed at 0.551207 and 0.551209 rather than at 0.500000 and 0.600000. Why?', '["So the two probes sit inside the interval where the chart Kb warning is already firing on both rows.", "So the two probes sit either side of the measured critical ratio and the size of the step is visible rather than asserted.", "So the two probes avoid the outlet fractions the published gas cases already occupy.", "So the two probes land on the two areas the published set prints for the subcritical branch."]'::jsonb, 1, 'Probes chosen a millionth either side make the branch change visible without a change of anything else. The published subcritical rows sit at quite different conditions again.'),
  ('relief', 'beginner', 'final', null, 24, 'A gas case at an outlet fraction of 0.400000 carries a warning and its required area is 2.223779 in2, the same as at 0.100000. What is the warning about?', '["The branch being about to turn over, since 0.400000 is approaching the critical ratio.", "The typed Kb having been ignored, since the outlet fraction has passed the measured edge.", "The chart Kb a balanced bellows valve needs above a measured outlet fraction of 0.300000.", "The required area having stopped moving, which the engine flags as a possible input error."]'::jsonb, 2, 'The area is flat across the whole choked range whether a warning fires or not, so the warning and the flatness are answers to different questions. The ignored Kb notice belongs to the subcritical branch.'),
  ('relief', 'beginner', 'final', null, 25, 'One gas case is run at allowances of 10.000000 and 25.000000 percent, giving 2.223779 in2 and 1.964194 in2. What decides which of those answers is the right one?', '["The contingency being sized for, since the allowance is part of choosing the case and the engine takes whatever percentage it is handed.", "The branch, since a choked case is customarily allowed the larger of the two accumulations.", "The certified coefficient, since a valve certified at one allowance cannot be sized at another.", "The orifice ladder, since the allowance that lands furthest from a rung is the one to take."]'::jsonb, 0, 'Those are two different questions with one answer each rather than two answers to one question. A fire case is customarily allowed more accumulation than a process case, and the engine takes the percentage without comment.'),
  ('relief', 'beginner', 'final', null, 26, 'What is a published case a demonstration of?', '["That this implementation and the published one agree at one set of inputs.", "That the answer this implementation returns at that set of inputs is a correct one.", "That every behaviour on the route has been reached by at least one row.", "That the constants inside the equation have each been checked separately."]'::jsonb, 0, 'It is a narrower claim than correctness and a more useful one. The interesting question about any published set is always which behaviours it leaves unvisited.'),
  ('relief', 'beginner', 'final', null, 27, 'Which single published gas row can detect a coefficient that multiplies where it should divide?', '["The one at the lowest relieving pressure, where a coefficient error is largest in proportion.", "The one at a Kd of 0.900000, a Kb of 0.880000 and a Kc of 0.900000.", "The pair of subcritical rows, since only there do all three coefficients enter the same form.", "Any of the five, since a coefficient of 1.000000 still divides or multiplies an area that is not one."]'::jsonb, 1, 'One divided by one and one multiplied by one are the same number, so a case at default coefficients cannot tell the two arrangements apart. Four of the five rows sit at the measured defaults.'),
  ('relief', 'beginner', 'final', null, 28, 'Which published block puts a row where a fit term that is worth almost nothing elsewhere carries most of the sum?', '["The steam block, at a relieving pressure of 1550.000000 psia.", "The gas block, at an outlet pressure of 400.000000 psia.", "The liquid block, at a Reynolds number of 92.428866.", "The gas block, at coefficients away from the engine defaults."]'::jsonb, 2, 'Without a case down there the steepest term of the viscosity fit would never be exercised by any published row. The steam row at 1550.000000 psia is valuable for a different reason, which is the interval where the correction is below one.'),
  ('relief', 'beginner', 'final', null, 29, 'On an active steam row the published correction reads 0.998366 and the returned one 0.998342. What is that difference?', '["A tolerance that the validation suite allows itself on a fit it cannot derive independently.", "The step that the correction takes at its published threshold, caught between the two evaluations.", "One published fit evaluated twice, which is why the digest prints both columns side by side.", "The superheat factor on that row, which the published answer applies and the re-run of it does not."]'::jsonb, 2, 'A tolerance is a property of a check rather than of two numbers, and the superheat factor on that row is 1.000000 on both sides. The row sits inside the interval where the correction is below one.'),
  ('relief', 'beginner', 'final', null, 30, 'A published set is described as agreeing with the engine to better than two parts in a thousand. Where does that figure come from?', '["A relative difference column the digest computes between the published answer and the re-run answer.", "A tolerance the validation suite declares before any case is run against it.", "The precision the digest prints each quantity at, which sets the smallest difference visible.", "The residual the loop stopped on, which bounds how far the re-run answer can be from the published one."]'::jsonb, 0, 'It is one of the very few two figure relationships in this course that a lesson may quote, because the digest works it out rather than a reader forming it. A residual belongs to an iteration and is a statement about the loop.'),
  ('relief', 'beginner', 'final', null, 31, 'A gauge pressure is fed to the gas route where an absolute one was wanted. What does the engine do?', '["It refuses, because every pressure argument is validated against its declared range.", "It returns a perfectly finite area that is wrong by whatever the conversion was.", "It converts the figure, because the route knows which datum its own argument carries.", "It returns an area with a warning, because the outlet fraction lands outside its usual band."]'::jsonb, 1, 'No guard anywhere in the module catches a unit. The error is about one atmosphere, which is small enough to read as a rounding difference and large enough to matter.'),
  ('relief', 'beginner', 'final', null, 32, 'Two of the three sizing routes in this tier have to raise a stated set pressure to an absolute one before the equation runs. Which two, and what forces it?', '["Gas and liquid, because a fraction of two pressures is only meaningful once both are absolute.", "Steam and liquid, because the published forms of both were written at an absolute datum.", "Gas and steam, because a mass flux through a throat depends on an absolute upstream pressure.", "All three of them, because a relieving pressure is an absolute pressure by the definition this course uses."]'::jsonb, 2, 'The gas route does form a fraction of two pressures, but both of them are absolute before that fraction exists, so forming it is not what forces the conversion. The steam route forms no fraction at all and still needs its pressure in psia.'),
  ('relief', 'beginner', 'final', null, 33, 'A reading is reported to four decimals where the engine returned 2.223779 in2. What is wrong with that?', '["It is quoted at a precision this course reserves for a measured constant, which is twelve decimals.", "It is quoted at the precision of a flow, which is correct only for a load in lb/hr or gpm.", "Nothing, since a required area is compared against a published table carrying three decimals.", "It is quoted at a precision this course does not declare for an area, which is six decimals."]'::jsonb, 3, 'Areas, pressures, dimensionless ratios and the gas coefficient print to six decimals, flows and duties to four, and measured constants to twelve. Rounding a reading shorter than the declared precision turns a correct answer into a wrong one.'),
  ('relief', 'beginner', 'final', null, 34, 'Which set of units does this tier speak?', '["Gas and steam loads in lb/hr, liquid loads in gpm, pressures in psia except where a row says psig, temperatures in degR and areas in in2.", "Gas and steam loads in lb/hr, liquid loads in gpm, pressures in psig throughout, temperatures in degF and areas in in2.", "Gas and steam loads in lb/hr, liquid loads in acfs, pressures in psia except where a row says psig, temperatures in degR and areas in ft2.", "All three loads in lb/hr, pressures in psia except where a row says psig, temperatures in degR and areas in in2."]'::jsonb, 0, 'The gauge cases are the liquid route and every stated set pressure. A degF temperature fed where degR is wanted produces a finite and badly wrong area, and no guard catches it.'),
  ('relief', 'beginner', 'final', null, 35, 'State the thesis this whole course rests on.', '["Every number the engine returns has been checked against a published case, so the sizing it produces can be trusted.", "Every number the engine returns is the size that one chosen case demands, and the engine never chooses the case.", "Every number the engine returns is either computed or typed, so a reader can always say which.", "Every number the engine returns is exact for the inputs given, so the answers cannot disagree."]'::jsonb, 1, 'Hand it a load and it will tell you what area passes that load, and it will never tell you that the load was the wrong one. The computed against typed reading is the skill this tier builds on top of that thesis.'),
  ('relief', 'beginner', 'final', null, 36, 'Which route computes the load it sizes for, and which tier takes it apart?', '["The gas and vapour route, at the Professional tier.", "The blowdown march, at the Expert tier.", "The fire case, at the Professional tier.", "The liquid route, at the Associate tier."]'::jsonb, 2, 'It computes the load from a geometry, a drainage answer and an environment factor that the caller states. The blowdown march empties a vessel rather than sizing a valve for a load.'),
  ('relief', 'beginner', 'final', null, 37, 'What is the one shape every column of the three stream summary shares?', '["A stated load and conditions, a relieving pressure, two computed factors, a stated coefficient, an area and a letter.", "A stated load and conditions, a relieving pressure, one computed factor, one typed factor, a stated coefficient, an area, a letter and a margin.", "A stated load and conditions, a relieving pressure, one computed factor, one typed factor, an area, a letter and a governing case.", "A stated load, a set pressure, an outlet pressure, a branch, one computed factor, an area and a letter."]'::jsonb, 1, 'Nothing in the tier ranks one of the three against another, and the digest prints no relation between them. Choosing between scenarios happens within one protected item.'),
  ('relief', 'beginner', 'final', null, 38, 'A candidate reports a branch as 0.551208 rather than as a word. What has gone wrong?', '["Nothing, since the critical ratio and the branch are two renderings of one answer.", "A branch is reported as an outlet fraction, so the figure should have been 0.104258.", "A branch is reported as a factor, so the figure quoted should have been the F2 that the case returned.", "A branch is a regime the engine reports, and 0.551208 is the critical ratio that decides it."]'::jsonb, 3, 'Report the branch as a word and the correction as the figure returned. Where a reading is a ratio, say what it is a ratio of, because this module carries several and they are not interchangeable.'),
  ('relief', 'beginner', 'final', null, 39, 'Seven exports in this module return a bare number. How does one of them refuse?', '["By returning zero, which a caller is expected to test for before using the figure.", "By returning NaN, since a bare number has no room for an `error` string beside it.", "By returning null, which is the same absence that an inviscid Reynolds field carries.", "By throwing, which is why a caller has to wrap those seven in a guard of their own."]'::jsonb, 1, 'The twelve object routes are the ones that can carry an `error` string. Nothing in this module throws, and the null is what an inviscid liquid call returns in place of a Reynolds number.'),
  ('relief', 'beginner', 'final', null, 40, 'Which subject does this course hand back to another course by name?', '["The flare setback and its allowable radiant intensities, which belong to the separation course.", "The knockout drum length, which belongs to the gas processing course.", "The viscosity correction on a liquid valve, which belongs to the line sizing course.", "The critical pressure ratio on a gas valve, which belongs to the gas lift course."]'::jsonb, 0, 'Gas lift owns critical flow through an injection port, which is the same nozzle relation solved for a throughput rather than for an area. The drum length is sized in this engine at the Professional tier.'),
  ('relief', 'beginner', 'final', null, 41, 'A learner asks which of two relief cases on a train is the governing one. What does this tier answer?', '["The one with the larger required area, since the governing case on any train is the one that demands the most valve.", "The one with the larger relief load, once both loads are converted into the same unit.", "The one whose margin is smallest, since that case is the closest to needing a larger orifice.", "Nothing, because choosing between scenarios happens within one protected item and this engine never chooses a case."]'::jsonb, 3, 'Two cases on different equipment cannot be ranked at all, and the loads are not even in the same units. A larger required area within one protected item is a different question from a comparison across a train.'),
  ('relief', 'beginner', 'final', null, 42, 'Which four figures in this tier arrive as TYPED inputs, so a reader would have to go and read a chart or a table to check them?', '["Kb, Kw, KSH and the three coefficients of the viscosity fit.", "The two Napier boundaries, the coefficient C and the fourteen published orifice areas.", "Kb, Kw, KSH and the fourteen published orifice areas.", "Kd, Kc, the critical pressure ratio and the fourteen published orifice areas."]'::jsonb, 2, 'Those four are the typed set: three chart or table factors and one published table of areas. The viscosity fit is held for literature, a different status, and no caller types it in, because the engine evaluates it. The coefficient C and the critical ratio are closed forms.');
